display.text:
/**
 * Lightweight MessagePort RPC (no external framework).
 * Five message kinds: request / response / subscribe / unsubscribe / event.
 * Protocol spec: docs/rpc-protocol.md
 */

import type { ApiMethod, ApiParams, ApiResult, StreamTopic, Streams } from "./api";
import { RpcError, type RpcErrorShape } from "./types.ts";
import { ToolchainError } from "../shared/toolchains/errors.ts";

// ---------------------------------------------------------------------------
// Wire protocol
// ---------------------------------------------------------------------------

export type WireRequest = {
  kind: "request";
  id: string;
  method: string;
  params: unknown;
};

export type WireResponse = {
  kind: "response";
  id: string;
  ok: boolean;
  result?: unknown;
  error?: RpcErrorShape;
};

export type WireEvent = {
  kind: "event";
  topic: string;
  key: string;
  data: unknown;
};

export type WireSubscribe = {
  kind: "subscribe";
  id: string;
  topic: string;
  key: string;
};

export type WireUnsubscribe = {
  kind: "unsubscribe";
  id: string;
  topic: string;
  key: string;
};

export type WireMessage = WireRequest | WireResponse | WireEvent | WireSubscribe | WireUnsubscribe;

// ---------------------------------------------------------------------------
// Client (renderer / any consumer)
// ---------------------------------------------------------------------------

export interface PiRpc {
  call<M extends ApiMethod>(
    method: M,
    ...args: ApiParams<M> extends void ? [] | [void] : [ApiParams<M>]
  ): Promise<ApiResult<M>>;
  subscribe<T extends StreamTopic>(topic: T, key: string, on: (ev: Streams[T]) => void): () => void;
  close(): void;
}

type Pending = {
  resolve: (v: unknown) => void;
  reject: (e: Error) => void;
  timer: ReturnType<typeof setTimeout>;
};

type SubEntry = {
  topic: string;
  key: string;
  handler: (ev: unknown) => void;
};

let nextId = 0;
function makeId(): string {
  nextId += 1;
  return `r${nextId}_${Date.now().toString(36)}`;
}

export type RpcClientOptions = {
  callTimeoutMs?: number;
};

const DEFAULT_CALL_TIMEOUT_MS = 120_000;

type RpcClientPort = {
  addEventListener(type: "message", listener: (event: MessageEvent) => void): void;
  addEventListener(type: "close", listener: () => void): void;
  removeEventListener(type: "message", listener: (event: MessageEvent) => void): void;
  removeEventListener(type: "close", listener: () => void): void;
  postMessage(message: unknown): void;
  start(): void;
  close(): void;
};

export function createRpcClient(port: RpcClientPort, options: RpcClientOptions = {}): PiRpc {
  const pending = new Map<string, Pending>();
  const subs = new Map<string, SubEntry>();
  const configuredTimeout = options.callTimeoutMs;
  const callTimeoutMs =
    typeof configuredTimeout === "number" && Number.isFinite(configuredTimeout) && configuredTimeout > 0
      ? configuredTimeout
      : DEFAULT_CALL_TIMEOUT_MS;

  const rejectPending = (shape: RpcErrorShape) => {
    for (const [, entry] of pending) {
      clearTimeout(entry.timer);
      entry.reject(new RpcError(shape));
    }
    pending.clear();
  };

  const onMessage = (ev: MessageEvent) => {
    const msg = ev.data as WireMessage;
    if (!msg || typeof msg !== "object") return;

    if (msg.kind === "response") {
      const p = pending.get(msg.id);
      if (!p) return;
      pending.delete(msg.id);
      clearTimeout(p.timer);
      if (msg.ok) p.resolve(msg.result);
      else {
        p.reject(new RpcError(msg.error ?? { code: "UNKNOWN", message: "Unknown RPC error" }));
      }
      return;
    }

    if (msg.kind === "event") {
      for (const sub of subs.values()) {
        if (sub.topic === msg.topic && (sub.key === "*" || sub.key === msg.key || msg.key === "*")) {
          try {
            sub.handler(msg.data);
          } catch {
            /* ignore subscriber errors */
          }
        }
      }
    }
  };

  const onClose = () => {
    rejectPending({ code: "CLOSED", message: "RPC port closed" });
    subs.clear();
  };

  port.addEventListener("message", onMessage);
  port.addEventListener("close", onClose);
  port.start();

  return {
    call(method, ...args) {
      const params = (args[0] ?? undefined) as unknown;
      const id = makeId();
      return new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
          if (!pending.delete(id)) return;
          reject(new RpcError({ code: "TIMEOUT", message: `RPC call timed out: ${String(method)}` }));
        }, callTimeoutMs);
        pending.set(id, {
          resolve: resolve as (v: unknown) => void,
          reject,
          timer,
        });
        const req: WireRequest = {
          kind: "request",
          id,
          method: method as string,
          params,
        };
        try {
          port.postMessage(req);
        } catch (err) {
          pending.delete(id);
          clearTimeout(timer);
          reject(err instanceof Error ? err : new Error(String(err)));
        }
      });
    },

    subscribe(topic, key, on) {
      const id = makeId();
      const msg: WireSubscribe = {
        kind: "subscribe",
        id,
        topic: topic as string,
        key,
      };
      port.postMessage(msg);
      subs.set(id, {
        topic: topic as string,
        key,
        handler: on as (ev: unknown) => void,
      });
      return () => {
        subs.delete(id);
        const unsub: WireUnsubscribe = {
          kind: "unsubscribe",
          id,
          topic: topic as string,
          key,
        };
        try {
          port.postMessage(unsub);
        } catch {
          /* ignore */
        }
      };
    },

    close() {
      port.removeEventListener("message", onMessage);
      port.removeEventListener("close", onClose);
      rejectPending({ code: "CLOSED", message: "RPC port closed" });
      subs.clear();
      try {
        port.close();
      } catch {
        /* ignore */
      }
    },
  };
}

// ---------------------------------------------------------------------------
// Server (agent-host)
// ---------------------------------------------------------------------------

export type RpcRequestContext = {
  setLease(key: string, release: () => void): void;
  releaseLease(key: string): boolean;
};

export type ApiHandler = {
  [M in ApiMethod]?: (params: ApiParams<M>, context: RpcRequestContext) => Promise<ApiResult<M>> | ApiResult<M>;
};

export type StreamSink = {
  topic: string;
  key: string;
  emit: (data: unknown) => void;
};

/**
 * Port shape that works in both:
 * - Renderer DOM MessagePort (addEventListener + MessageEvent.data)
 * - utilityProcess / Node worker_threads MessagePort (EventEmitter .on('message'))
 * - Electron MessagePortMain (.on('message', (e) => e.data))
 */
export type AnyMessagePort = {
  postMessage: (message: unknown, transfer?: unknown[]) => void;
  start?: () => void;
  close?: () => void;
  addEventListener?: (type: string, listener: (ev: { data: unknown }) => void) => void;
  removeEventListener?: (type: string, listener: (ev: { data: unknown }) => void) => void;
  on?: (event: string, listener: (...args: unknown[]) => void) => void;
  off?: (event: string, listener: (...args: unknown[]) => void) => void;
  removeListener?: (event: string, listener: (...args: unknown[]) => void) => void;
};

export interface RpcServer {
  handle(handlers: ApiHandler): void;
  emit<T extends StreamTopic>(topic: T, key: string, data: Streams[T]): void;
  attachPort(port: AnyMessagePort): void;
  detachPort(port: AnyMessagePort): void;
}

function extractMessageData(arg: unknown): unknown {
  // DOM MessageEvent / Electron MessagePortMain event: { data }
  if (arg && typeof arg === "object" && "data" in arg && !("kind" in arg)) {
    return (arg as { data: unknown }).data;
  }
  // Node worker_threads MessagePort: payload is the value itself
  return arg;
}

function listenPort(port: AnyMessagePort, onData: (data: unknown) => void): () => void {
  if (typeof port.addEventListener === "function") {
    const listener = (ev: { data: unknown }) => onData(ev.data);
    port.addEventListener("message", listener);
    port.start?.();
    return () => port.removeEventListener?.("message", listener);
  }

  if (typeof port.on === "function") {
    const listener = (...args: unknown[]) => {
      onData(extractMessageData(args[0]));
    };
    port.on("message", listener);
    port.start?.();
    return () => {
      port.off?.("message", listener);
      port.removeListener?.("message", listener);
    };
  }

  throw new Error("MessagePort has neither addEventListener nor on()");
}

export function createRpcServer(): RpcServer {
  const handlers = new Map<string, (params: unknown, context: RpcRequestContext) => Promise<unknown> | unknown>();
  const ports = new Set<AnyMessagePort>();
  /** port → subscription id → { topic, key } */
  const portSubs = new Map<AnyMessagePort, Map<string, { topic: string; key: string }>>();
  const portUnlisten = new Map<AnyMessagePort, () => void>();
  const portCloseUnlisten = new Map<AnyMessagePort, () => void>();
  const portLeases = new Map<AnyMessagePort, Map<string, () => void>>();

  function forgetPort(port: AnyMessagePort): void {
    ports.delete(port);
    portSubs.delete(port);
    const leases = portLeases.get(port);
    portLeases.delete(port);
    for (const release of leases?.values() ?? []) {
      try {
        release();
      } catch {
        /* isolate resource finalizers */
      }
    }
    portUnlisten.get(port)?.();
    portUnlisten.delete(port);
    portCloseUnlisten.get(port)?.();
    portCloseUnlisten.delete(port);
  }

  function requestContext(port: AnyMessagePort): RpcRequestContext {
    return {
      setLease(key, release) {
        if (!ports.has(port)) {
          release();
          return;
        }
        const leases = portLeases.get(port) ?? new Map<string, () => void>();
        const previous = leases.get(key);
        leases.set(key, release);
        portLeases.set(port, leases);
        if (previous && previous !== release) previous();
      },
      releaseLease(key) {
        const leases = portLeases.get(port);
        const release = leases?.get(key);
        if (!release) return false;
        leases?.delete(key);
        try {
          release();
        } catch {
          /* isolate explicit resource release */
        }
        return true;
      },
    };
  }

  function ensureSubs(port: AnyMessagePort): Map<string, { topic: string; key: string }> {
    let m = portSubs.get(port);
    if (!m) {
      m = new Map();
      portSubs.set(port, m);
    }
    return m;
  }

  async function onPortMessage(port: AnyMessagePort, raw: unknown) {
    const msg = raw as WireMessage;
    if (!msg || typeof msg !== "object") return;

    if (msg.kind === "subscribe") {
      ensureSubs(port).set(msg.id, { topic: msg.topic, key: msg.key });
      return;
    }
    if (msg.kind === "unsubscribe") {
      ensureSubs(port).delete(msg.id);
      return;
    }
    if (msg.kind !== "request") return;

    const handler = handlers.get(msg.method);

    let response: WireResponse;
    try {
      if (!handler) {
        throw new RpcError({
          code: "METHOD_NOT_FOUND",
          message: `Unknown method: ${msg.method}`,
        });
      }
      const result = await handler(msg.params, requestContext(port));
      response = { kind: "response", id: msg.id, ok: true, result };
    } catch (err) {
      const error: RpcErrorShape =
        err instanceof RpcError
          ? { code: err.code, message: err.message, detail: err.detail }
          : err instanceof ToolchainError
            ? {
                code: err.code,
                message: err.message,
                detail: { capability: err.capability, causeCode: err.causeCode },
              }
            : {
                code: "INTERNAL",
                message: err instanceof Error ? err.message : String(err),
              };
      response = { kind: "response", id: msg.id, ok: false, error };
    }
    try {
      port.postMessage(response);
    } catch {
      const fallback: WireResponse = {
        kind: "response",
        id: msg.id,
        ok: false,
        error: { code: "SERIALIZATION_FAILED", message: "RPC response could not be serialized" },
      };
      try {
        port.postMessage(fallback);
      } catch {
        forgetPort(port);
        try {
          port.close?.();
        } catch {
          /* ignore a transport that is already closed */
        }
      }
    }
  }

  return {
    handle(next) {
      for (const [method, handler] of Object.entries(next)) {
        if (typeof handler === "function")
          handlers.set(method, handler as (params: unknown, context: RpcRequestContext) => Promise<unknown> | unknown);
      }
    },

    emit(topic, key, data) {
      const wire: WireEvent = {
        kind: "event",
        topic: topic as string,
        key,
        data,
      };
      for (const port of ports) {
        const subs = portSubs.get(port);
        if (!subs) continue;
        let match = false;
        for (const sub of subs.values()) {
          if (sub.topic === topic && (sub.key === "*" || sub.key === key || key === "*")) {
            match = true;
            break;
          }
        }
        if (!match) continue;
        try {
          port.postMessage(wire);
        } catch {
          forgetPort(port);
          try {
            port.close?.();
          } catch {
            /* ignore a transport that is already closed */
          }
        }
      }
    },

    attachPort(port) {
      if (ports.has(port)) return;
      ports.add(port);
      ensureSubs(port);
      portLeases.set(port, new Map());
      const unlisten = listenPort(port, (data) => {
        void onPortMessage(port, data);
      });
      portUnlisten.set(port, unlisten);
      // ISSUE-013: drop port when remote closes
      const onClose = () => {
        forgetPort(port);
      };
      if (typeof port.addEventListener === "function") {
        port.addEventListener("close", onClose as (ev: { data: unknown }) => void);
        portCloseUnlisten.set(port, () => {
          port.removeEventListener?.("close", onClose as (ev: { data: unknown }) => void);
        });
      } else if (typeof port.on === "function") {
        port.on("close", onClose);
        portCloseUnlisten.set(port, () => {
          if (typeof port.off === "function") port.off("close", onClose);
          else port.removeListener?.("close", onClose);
        });
      }
    },

    detachPort(port) {
      if (!ports.has(port)) return;
      forgetPort(port);
      try {
        port.close?.();
      } catch {
        /* ignore */
      }
    },
  };
}

import type {
  AgentCommand,
  AgentEvent,
  CredentialMutationResult,
  DirEntry,
  EntryContentResult,
  FileContent,
  FileMeta,
  HistoryWindow,
  LoginProgressEvent,
  ModelPreferencesResult,
  ModelsConfig,
  ModelsConfigSnapshot,
  ModelsListResult,
  PagedContextInfo,
  ProviderStatus,
  RunningStateEvent,
  SessionDetail,
  SessionInfo,
  TestResult,
  WorktreeInfo,
} from "./types";
import type {
  GitStatusResult,
  PluginActionParams,
  PluginsResponse,
  SkillRecord,
  SkillUpdateParams,
} from "../shared/api-types";
import type {
  ChannelAccountConfig,
  ChannelBinding,
  ChannelBindingChange,
  ChannelLoginEvent,
  ChannelLoginStartRequest,
  ChannelProbeResult,
  ChannelsSnapshot,
  ChannelStatus,
  ChannelPairingRequest,
  ChannelActivity,
  ChannelId,
  ChannelTestSendResult,
} from "../shared/channel-types";
import type { ToolCapabilityId, ToolProvider } from "../shared/toolchains/types";
import type {
  ManagedProcessChangedEvent,
  ManagedProcessLogStream,
  ManagedProcessLogWindow,
  ManagedProcessOutputEvent,
  ManagedProcessPublicInfo,
  ManagedProcessReadParams,
  ManagedProcessWaitParams,
  ManagedProcessWriteParams,
} from "./processes";

/** Request/response API surface (replaces HTTP routes). */
export interface Api {
  "host.ping": { params: void; result: { ok: true; ts: number } };
  "host.toolchain": {
    params: { cwd: string };
    result: {
      inventoryRevision: number;
      resolutionId: string;
      capabilities: Partial<Record<ToolCapabilityId, { provider: ToolProvider; version: string }>>;
    };
  };

  // Managed background processes (trusted Renderer control surface)
  "processes.list": {
    params: { includeExited?: boolean } | void;
    result: { revision: number; processes: ManagedProcessPublicInfo[] };
  };
  "processes.get": {
    params: { processId: string };
    result: ManagedProcessPublicInfo;
  };
  "processes.read": {
    params: ManagedProcessReadParams;
    result: ManagedProcessLogWindow;
  };
  "processes.wait": {
    params: ManagedProcessWaitParams;
    result: ManagedProcessLogWindow;
  };
  "processes.write": {
    params: ManagedProcessWriteParams;
    result: { ok: true; runId: string };
  };
  "processes.stop": {
    params: { processId: string; runId: string; mode?: "graceful" | "force" };
    result: ManagedProcessPublicInfo;
  };
  "processes.stopAll": {
    params: { mode?: "graceful" | "force" } | void;
    result: { ok: true; stopped: number };
  };
  "processes.restart": {
    params: { processId: string; runId: string };
    result: ManagedProcessPublicInfo;
  };
  "processes.dismiss": {
    params: { processId: string };
    result: { ok: true };
  };
  "processes.export": {
    params: { processId: string; runId: string; streams?: ManagedProcessLogStream[] };
    result: { saved: boolean; fileName?: string };
  };

  // Sessions & projects
  "sessions.list": {
    params: { cwd?: string } | void;
    result: { sessions: SessionInfo[]; runningSessionIds: string[] };
  };
  "sessions.get": {
    params: { id: string; includeState?: boolean; traceId?: string; historyWindow?: HistoryWindow };
    result: SessionDetail;
  };
  "sessions.context": {
    params: { id: string; leafId?: string; historyWindow?: HistoryWindow };
    result: { context: PagedContextInfo };
  };
  "sessions.contextPage": {
    params: { id: string; cursor: string; maxTurns?: number; maxBytes?: number };
    result: { context: PagedContextInfo };
  };
  "sessions.entryContent": {
    params: { id: string; entryId: string; blockIndex?: number };
    result: EntryContentResult;
  };
  "sessions.export": {
    params: { id: string; format?: "md" | "json" };
    result: { content: string; suggestedName: string };
  };
  "sessions.delete": { params: { id: string; force?: boolean }; result: { ok: true } };
  "sessions.rename": {
    params: { id: string; name: string };
    result: { ok: true };
  };

  "worktrees.list": {
    params: { projectRoot: string };
    result: {
      worktrees: WorktreeInfo[];
      projectRoot: string;
      isGit: boolean;
      isTopLevel: boolean;
    };
  };
  "worktrees.create": {
    params: { projectRoot: string; branch: string; cwd?: string };
    result: { worktree: WorktreeInfo };
  };
  "worktrees.remove": {
    params: { path: string; cwd?: string; force?: boolean };
    result: { ok: true };
  };

  "git.status": {
    params: { path: string };
    result: GitStatusResult;
  };

  // Agent lifecycle
  "agent.new": {
    params: {
      cwd: string;
      type?: string;
      message?: string;
      provider?: string;
      modelId?: string;
      toolNames?: string[];
      thinkingLevel?: string;
      [key: string]: unknown;
    };
    result: { sessionId: string; data?: unknown };
  };
  "agent.command": {
    params: { sessionId: string; command: AgentCommand };
    result: unknown;
  };
  "agent.state": {
    params: { sessionId: string };
    result: { running: boolean; state?: unknown };
  };
  /** Generate a concise session title from the first user message (silent LLM request, never touches session history). */
  "agent.generateTitle": {
    params: {
      sessionId: string;
      message: string;
      provider?: string;
      modelId?: string;
    };
    result: { title: string | null };
  };

  // Messaging channels
  "channels.list": { params: void; result: ChannelsSnapshot };
  "channels.accountUpsert": {
    params: { account: ChannelAccountConfig };
    result: ChannelsSnapshot;
  };
  "channels.accountConnect": {
    params: { account: ChannelAccountConfig };
    result: ChannelsSnapshot;
  };
  "channels.accountDelete": {
    params: { accountId: string };
    result: ChannelsSnapshot;
  };
  "channels.start": { params: { accountId: string }; result: { ok: true } };
  "channels.stop": { params: { accountId: string }; result: { ok: true } };
  "channels.restart": { params: { accountId: string }; result: { ok: true } };
  "channels.probe": { params: { accountId: string }; result: ChannelProbeResult };
  "channels.loginStart": {
    params: ChannelLoginStartRequest;
    result: ChannelLoginEvent;
  };
  "channels.loginWait": {
    params: { channel: ChannelId; sessionKey: string };
    result: ChannelLoginEvent;
  };
  "channels.loginSubmitCode": {
    params: { channel: ChannelId; sessionKey: string; code: string };
    result: { ok: true };
  };
  "channels.loginCancel": {
    params: { channel: ChannelId; sessionKey: string };
    result: { ok: true };
  };
  "channels.pairingApprove": {
    params: { pairingId: string };
    result: ChannelsSnapshot;
  };
  "channels.pairingReject": {
    params: { pairingId: string };
    result: ChannelsSnapshot;
  };
  "channels.bindingUpsert": {
    params: { binding: ChannelBinding };
    result: ChannelsSnapshot;
  };
  "channels.bindingDelete": {
    params: { bindingId: string };
    result: ChannelsSnapshot;
  };
  "channels.testSend": {
    params: { accountId: string; peerId: string; message: string };
    result: ChannelTestSendResult;
  };

  // Files
  "files.list": { params: { path: string }; result: { entries: DirEntry[] } };
  "files.read": {
    params: { path: string; sourceSessionId?: string };
    result: FileContent & {
      encoding?: "utf8" | "base64" | "too_large";
      mime?: string;
    };
  };
  "files.download": {
    params: { path: string; sourceSessionId?: string };
    result: { base64: string; size: number; mime: string };
  };
  "files.meta": {
    params: { path: string; sourceSessionId?: string };
    result: FileMeta;
  };
  "files.preview": {
    params: { path: string; sourceSessionId?: string };
    result: { kind: string; content?: string; base64?: string; mime?: string; [key: string]: unknown };
  };
  "files.index": {
    params: { root: string; query?: string };
    result: {
      files: string[];
      truncated: boolean;
      truncatedReason?: "depth" | "count";
      matches?: Array<{ path: string; isDir?: boolean; score?: number }>;
      degradedReason?: "search-unavailable" | "search-timeout" | "search-failed";
    };
  };
  "files.watchStart": {
    params: { path: string; sourceSessionId?: string };
    result: { ok: true };
  };
  "files.watchStop": {
    params: { path: string };
    result: { ok: true };
  };

  // Config
  "models.list": {
    params: { cwd?: string } | void;
    result: ModelsListResult;
  };
  "models.refresh": {
    params: { cwd?: string; requestId: string };
    result: ModelsListResult;
  };
  "models.refreshCancel": {
    params: { requestId: string };
    result: { ok: true; cancelled: boolean };
  };
  "models.preferences.get": {
    params: { cwd?: string } | void;
    result: ModelPreferencesResult;
  };
  "models.preferences.set": {
    params: { cwd?: string; enabledModels: string[] | null };
    result: ModelPreferencesResult;
  };
  "modelsConfig.get": { params: void; result: ModelsConfigSnapshot };
  "modelsConfig.set": {
    params: { config: ModelsConfig; expectedVersion: string };
    result: { ok: true; version: string };
  };
  "modelsConfig.test": {
    params: {
      providerName?: string;
      provider?: Record<string, unknown>;
      model?: Record<string, unknown>;
      [key: string]: unknown;
    };
    result: TestResult;
  };

  "auth.providers": { params: void; result: { providers: ProviderStatus[] } };
  "auth.allProviders": { params: void; result: { providers: ProviderStatus[] } };
  "auth.setApiKey": {
    params: { provider: string; key: string };
    result: CredentialMutationResult;
  };
  "auth.deleteApiKey": {
    params: { provider: string };
    result: CredentialMutationResult;
  };
  "auth.logout": { params: { provider: string }; result: CredentialMutationResult };
  "auth.loginSubmit": {
    params: { provider: string; token: string; code: string };
    result: { ok: true };
  };
  /** Kick off OAuth login; progress arrives on Streams["auth.login"]. */
  "auth.loginStart": {
    params: { provider: string };
    result: { ok: true; started: boolean };
  };
  "auth.loginCancel": {
    params: { provider: string };
    result: { ok: true };
  };

  "skills.list": {
    params: { cwd?: string } | void;
    result: { skills: SkillRecord[]; diagnostics?: unknown[] };
  };
  "skills.search": {
    params: { query: string };
    result: { results: unknown[] };
  };
  "skills.install": {
    params: { package: string; [key: string]: unknown };
    result: { ok: true; [key: string]: unknown };
  };
  "skills.set": {
    params: SkillUpdateParams;
    result: { ok: true };
  };
  "skills.getContent": {
    params: { cwd: string; filePath: string };
    result: { content: string };
  };

  "plugins.list": {
    params: { cwd?: string } | void;
    result: PluginsResponse;
  };
  "plugins.set": {
    params: PluginActionParams;
    result: PluginsResponse;
  };

  // System / desktop helpers exposed via Host (or main-bridged)
  "system.home": { params: void; result: { home: string } };
  "system.validateCwd": {
    params: { path: string };
    result: { ok: boolean; path?: string; error?: string };
  };
  "system.defaultCwd": { params: void; result: { cwd: string } };
  "system.allowRoot": { params: { path: string }; result: { ok: true } };
  "system.runningCount": { params: void; result: { count: number; sessionIds: string[] } };
}

/** Server-push streams delivered over MessagePort RPC. */
export interface Streams {
  "agent.events": AgentEvent;
  "agent.running": RunningStateEvent;
  "auth.login": LoginProgressEvent;
  "sessions.changed": {
    cwd: string | null;
    sessionId?: string;
    session?: SessionInfo;
    deleted?: boolean;
    fullRefresh?: boolean;
  };
  "files.changed": {
    path: string;
    event: "connected" | "change" | "error";
    mtime?: string;
    size?: number;
    message?: string;
  };
  "channels.status": ChannelStatus;
  "channels.login": ChannelLoginEvent;
  "channels.pairing": ChannelPairingRequest;
  "channels.binding": ChannelBindingChange;
  "channels.activity": ChannelActivity;
  "processes.changed": ManagedProcessChangedEvent;
  "processes.output": ManagedProcessOutputEvent;
}

export type ApiMethod = keyof Api;
export type StreamTopic = keyof Streams;

export type ApiParams<M extends ApiMethod> = Api[M]["params"];
export type ApiResult<M extends ApiMethod> = Api[M]["result"];

